good_tools = [
    {
        "type": "function",
        "function": {
            "name": "query_sales_db",
            "description": (
                "Query the internal SQL sales database. "
                "Use this when the user asks about revenue, orders, "
                "quarterly sales numbers, or product performance. "
                "Example: 'Get Q1 sales for product X'."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "sql_query": {
                        "type": "string",
                        "description": "The SQL query to execute"
                    }
                },
                "required": ["sql_query"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "search_web",
            "description": (
                "Search the public internet for current news, "
                "general knowledge, or external market data. "
                "Do NOT use for internal company data."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "query": {
                        "type": "string",
                        "description": "The search query string"
                    }
                },
                "required": ["query"]
            }
        }
    }
]
